# Let me try a much simpler hypothesis:
# The pattern might be to just output all 1s that form "complete" rectangular frames

# Or it could be: count the number of frames surrounding each position

# Let me try filling ALL enclosed regions (regions of 0s completely surrounded by 1s)
from collections import deque

def fill_enclosed_regions(grid):
    h, w = len(grid), len(grid[0])

    # Flood fill from edges to mark reachable 0s
    reachable = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Check if on edge
                if r == 0 or r == h-1 or c == 0 or c == w-1:
                    try:
                        q = deque([(r,c)])
                        reachable[r][c] = True
                        while q:
                        _,_ = q.popleft()
                        rr, cc = _
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not reachable[nr][nc]:
                                reachable[nr][nc] = True
                                q.append((nr, nc))
                    except:
                        pass

    # Fill non-reachable 0s with 1s
    output = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                output[r][c] = 1
            elif not reachable[r][c]:
                output[r][c] = 1
            else:
                output[r][c] = 0

    return output

action = {"action": "submit", "grid": fill_enclosed_regions(grid)}
